// Extractor for t('message id') calls in .js files. Quick parser: matches
// only plain string-literal first arguments ('...' or "..."), so template
// literals and non-literal arguments are skipped. Merges results into an
// existing catalog without clobbering already-translated entries.

import {
  existsSync,
  readdirSync,
  readFileSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

// \b before t avoids matching part of identifiers like "format(" or "next(".
const CALL = /\bt\(\s*(["'])((?:\\.|(?!\1)[^\\])*)\1/g;

function unescapeLiteral(raw) {
  return raw.replaceAll(/\\(.)/g, (_, ch) =>
    ch === 'n' ? '\n' : ch === 't' ? '\t' : ch === 'r' ? '\r' : ch
  );
}

/** Pull message ids from a single source string. */
export function extractFromSource(source) {
  const ids = [];
  for (const match of String(source).matchAll(CALL)) ids.push(unescapeLiteral(match[2]));
  return ids;
}

function listJsFiles(path) {
  const abs = resolve(path);
  if (statSync(abs).isDirectory()) {
    return readdirSync(abs).flatMap((entry) => listJsFiles(join(abs, entry)));
  }
  return abs.endsWith('.js') ? [abs] : [];
}

/**
 * Scan files/directories for .js sources and return sorted unique message ids.
 * @param {string[]} paths
 */
export function extractIds(paths) {
  const ids = new Set();
  for (const path of paths) {
    for (const file of listJsFiles(path)) {
      for (const id of extractFromSource(readFileSync(file, 'utf8'))) ids.add(id);
    }
  }
  return [...ids].sort();
}

/**
 * Merge freshly extracted ids into a catalog object. Existing entries keep
 * their values (translations are never overwritten); new ids get "".
 * @param {string[]} ids sorted id list from extractIds()
 * @param {Record<string, string>} [existing]
 * @returns {Record<string, string>}
 */
export function mergeCatalog(ids, existing = {}) {
  const merged = {};
  // Preserve entries already in the catalog (translated or not), then add new ones.
  for (const [id, value] of Object.entries(existing)) merged[id] = value ?? '';
  for (const id of ids) if (!(id in merged)) merged[id] = '';
  return merged;
}

export function updateCatalogFile(ids, catalogPath) {
  const existing = existsSync(catalogPath)
    ? JSON.parse(readFileSync(catalogPath, 'utf8'))
    : {};
  const merged = mergeCatalog(ids, existing);
  writeFileSync(catalogPath, JSON.stringify(merged, null, 2) + '\n');
  return merged;
}

function main(argv) {
  const paths = [];
  let out = 'catalog.json';
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '-o' || argv[i] === '--out') out = argv[++i];
    else if (argv[i] === '-h' || argv[i] === '--help') {
      console.log('usage: node src/extract.mjs [-o catalog.json] file-or-dir...');
      process.exitCode = argv[i].startsWith('-') && argv[i] !== '-h' ? 1 : 0;
      return;
    } else paths.push(argv[i]);
  }
  if (paths.length === 0) {
    console.error('error: no input files or directories');
    process.exitCode = 1;
    return;
  }
  const ids = extractIds(paths);
  updateCatalogFile(ids, out);
  console.log(`extracted ${ids.length} message id(s) -> ${out}`);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  main(process.argv.slice(2));
}

