// ICU-lite message formatting: {name} interpolation, plural with exact
// matches (=0) and Intl.PluralRules categories, and select. Parsed with a
// recursive-descent parser so variants may contain arbitrarily nested braces.

const WS = /\s/;
const SUPPORTED_TYPES = new Set(['plural', 'select']);

function skipWs(src, i) {
  while (i < src.length && WS.test(src[i])) i++;
  return i;
}

function readWord(src, i) {
  const start = i;
  while (i < src.length && !WS.test(src[i]) && src[i] !== ',' && src[i] !== '{' && src[i] !== '}') i++;
  return [src.slice(start, i), i];
}

/**
 * Parse a sequence of nodes until end of input (nested === false) or until
 * the closing '}' of an enclosing variant (nested === true). Nested braces
 * are consumed by recursion into parseElement, so this loop only sees the
 * '}' that terminates *this* level.
 */
function parseSequence(src, i, nested) {
  const nodes = [];
  let text = '';
  while (i < src.length) {
    const ch = src[i];
    if (ch === '}') {
      if (!nested) throw new SyntaxError(`Unexpected '}' at offset ${i}`);
      return { nodes, i }; // caller consumes the '}'
    }
    if (ch === '{') {
      if (text) {
        nodes.push({ type: 'text', value: text });
        text = '';
      }
      const element = parseElement(src, i + 1);
      nodes.push(element.node);
      i = element.i;
      continue;
    }
    text += ch;
    i++;
  }
  if (nested) throw new SyntaxError('Unclosed { in message');
  return { nodes, i };
}

/** Parse one {argument ...} element; src[i] is just past the opening '{'. */
function parseElement(src, i) {
  const nameStart = i;
  while (i < src.length && src[i] !== ',' && src[i] !== '}') i++;
  if (i >= src.length) throw new SyntaxError('Unclosed { in message');
  const name = src.slice(nameStart, i).trim();
  if (!name) throw new SyntaxError(`Empty argument name at offset ${nameStart - 1}`);

  // Simple interpolation: {name}
  if (src[i] === '}') return { node: { type: 'arg', name }, i: i + 1 };

  // Styled argument: {name, type, options}
  if (src[i] !== ',') throw new SyntaxError(`Expected ',' or '}' after argument "${name}"`);
  i = skipWs(src, i + 1);
  let type;
  [type, i] = readWord(src, i);
  if (!SUPPORTED_TYPES.has(type)) throw new SyntaxError(`Unsupported style "${type}"`);
  i = skipWs(src, i);
  if (src[i] !== ',') throw new SyntaxError(`Expected ',' after style "${type}"`);
  i = skipWs(src, i + 1);

  const options = {};
  while (true) {
    i = skipWs(src, i);
    if (src[i] === '}') {
      i++;
      break;
    }
    const selectorStart = i;
    let selector;
    [selector, i] = readWord(src, i); // covers "one", "few", "many", "other", "=0", ...
    if (!selector) throw new SyntaxError(`Expected option selector at offset ${selectorStart}`);
    i = skipWs(src, i);
    if (src[i] !== '{') throw new SyntaxError(`Expected '{' after selector "${selector}"`);
    const body = parseSequence(src, i + 1, true);
    if (selector in options) throw new SyntaxError(`Duplicate selector "${selector}"`);
    options[selector] = body.nodes;
    i = body.i + 1; // consume '}'
  }
  return { node: { type, name, options }, i };
}

export function parseMessage(msg) {
  const { nodes, i } = parseSequence(String(msg), 0, false);
  if (i < String(msg).length) throw new SyntaxError('Trailing input');
  return nodes;
}

function stringify(value) {
  if (value == null) return `{?}`;
  return String(value);
}

/** Resolve a node list to a string. `count` is the nearest enclosing plural number ('#' support). */
function resolveNodes(nodes, values, locale, count) {
  let out = '';
  for (const node of nodes) {
    switch (node.type) {
      case 'text':
        // '#' inside plural sub-messages stands for the pluralized number.
        out += count != null ? node.value.replaceAll('#', String(count)) : node.value;
        break;
      case 'arg':
        out += stringify(values[node.name]);
        break;
      case 'select': {
        const raw = values[node.name];
        const key = raw != null ? String(raw) : undefined;
        const option = (key != null && node.options[key]) || node.options.other;
        if (!option) throw new Error(`No match for "${node.name}" and no "other" variant`);
        out += resolveNodes(option, values, locale, count);
        break;
      }
      case 'plural': {
        const num = Number(values[node.name]);
        if (values[node.name] == null || Number.isNaN(num)) {
          throw new Error(`Missing or non-numeric value for plural argument "${node.name}"`);
        }
        const exactKey = '=' + num; // Number() normalization: "0", 0, and 0.0 all match '=0'
        const category = new Intl.PluralRules(locale).select(num);
        const option = node.options[exactKey] || node.options[category] || node.options.other;
        if (!option) throw new Error(`No match for "${node.name}"=${num} and no "other" variant`);
        out += resolveNodes(option, values, locale, num);
        break;
      }
    }
  }
  return out;
}

/**
 * Format an ICU-lite message.
 *
 * @param {string} msg     message pattern
 * @param {object} values  interpolation values
 * @param {string} locale  BCP-47 locale used for plural categories
 */
export function format(msg, values = {}, locale = 'en') {
  return resolveNodes(parseMessage(msg), values, locale, null);
